// This file is generated by AI.

// 项目诊断的收集、筛选与导出 (纯函数, 不依赖 React / Tauri, 便于单测)。
//
// 语言服务是**按项目**诊断的: 每推送一次就是整个项目所有场景的结果, 没有问题的场景
// 推一个空数组 (不是不推)。因此 store 里那份 `diagnostics` 一直是"项目内全部场景的现状",
// 与某个文件此刻有没有被打开无关 —— 这正是"项目诊断列表"能显示未打开场景的前提。
//
// 这里只做三件事: 把那份表整理成按文件分组的列表、按条件筛选、导出 JSON。

import { stripTrailingSeparator, toPosix } from '../lib/paths';
import type { LspDiagnostic, LspStatus } from '../state/store';

/** LSP 严重级别: 1 错误 / 2 警告 / 3 信息 / 4 提示 */
export type Severity = 1 | 2 | 3 | 4;

/** 级别的固定展示顺序 (错误 → 警告 → 信息 → 提示), 与 `Severity` 的数值顺序一致 */
export const SEVERITY_ORDER: Severity[] = [1, 2, 3, 4];

export const SEVERITY_LABELS: Record<Severity, string> = {
  1: '错误',
  2: '警告',
  3: '信息',
  4: '提示',
};

/** 导出 JSON 里的级别名 (数字对读日志的人没有意义) */
const SEVERITY_NAMES: Record<Severity, string> = {
  1: 'error',
  2: 'warning',
  3: 'info',
  4: 'hint',
};

/** 默认关闭的级别: 信息级目前只有 WG001 的格式建议, 数量最多且不代表"坏了" */
const SEVERITY_DEFAULT_OFF: Severity[] = [3, 4];

export interface DiagnosticEntry {
  /** 绝对路径 (点击跳转用) */
  path: string;
  /** 项目内相对路径, 正斜杠 (game/scene/start.txt) */
  file: string;
  /** 相对 `game/scene/` 的路径 (start.txt / 支线/学园祭.txt) */
  scene: string;
  /** 1 起算的行号 (LSP 原始是 0 起算, 编辑器里显示的是 1 起算) */
  line: number;
  /** 1 起算的列号 */
  column: number;
  endLine: number;
  endColumn: number;
  severity: Severity;
  /** 诊断码 (如 WG007); 服务端未给时为空串 */
  code: string;
  message: string;
}

export interface DiagnosticFile {
  path: string;
  file: string;
  scene: string;
  entries: DiagnosticEntry[];
}

export interface ProjectDiagnostics {
  /** 项目内已被诊断过的场景文件数 (含没有问题的) */
  scenes: number;
  /** 有诊断的文件, 按场景路径排序 */
  files: DiagnosticFile[];
}

export interface CodeStat {
  code: string;
  severity: Severity;
  count: number;
}

export interface DiagnosticFilter {
  /** 选中的严重级别 */
  severities: Severity[];
  /** 选中的诊断码; `null` 表示"尚未限定", 等同于全选 */
  codes: string[] | null;
  /** 消息 / 文件名 / 诊断码 的关键词 */
  query: string;
}

const SCENE_PREFIX = 'game/scene/';

/**
 * 路径排序。
 *
 * 不用 `localeCompare`: 它的结果取决于运行环境的 locale, 同一个项目在两台机器上可能排出
 * 不同的顺序 (中文与 ASCII 的先后尤其不稳), 而"列表顺序每次打开都一样"是件必须的事。
 */
function comparePath(a: string, b: string): number {
  const left = a.toLowerCase();
  const right = b.toLowerCase();
  return left < right ? -1 : left > right ? 1 : 0;
}

function sceneRelative(file: string): string {
  return file.toLowerCase().startsWith(SCENE_PREFIX) ? file.slice(SCENE_PREFIX.length) : file;
}

function normalizeSeverity(raw: number): Severity {
  return raw === 1 || raw === 2 || raw === 3 || raw === 4 ? raw : 3;
}

function toEntry(path: string, file: string, scene: string, raw: LspDiagnostic): DiagnosticEntry {
  return {
    path,
    file,
    scene,
    line: raw.range.start.line + 1,
    column: raw.range.start.character + 1,
    endLine: raw.range.end.line + 1,
    endColumn: raw.range.end.character + 1,
    severity: normalizeSeverity(raw.severity),
    code: raw.code === undefined || raw.code === null ? '' : String(raw.code),
    message: raw.message,
  };
}

/**
 * 把 store 里按路径索引的诊断整理成按文件分组的列表。
 *
 * 只保留**当前项目**的路径: 诊断表的清空只在关闭项目时发生, 直接从一个项目切到另一个
 * 时上一份数据还在里面, 不按前缀过滤就会把别的项目的问题列出来。
 */
export function collectProjectDiagnostics(
  diagnostics: Record<string, LspDiagnostic[]>,
  projectPath: string | null
): ProjectDiagnostics {
  const prefix = projectPath ? `${toPosix(stripTrailingSeparator(projectPath)).toLowerCase()}/` : '';
  let scenes = 0;
  const files: DiagnosticFile[] = [];

  for (const [path, list] of Object.entries(diagnostics)) {
    const posix = toPosix(path);
    if (prefix && !posix.toLowerCase().startsWith(prefix)) continue;
    scenes += 1;
    // 没有问题的场景不占列表行, 但仍计入场景数
    if (list.length === 0) continue;
    const file = prefix ? posix.slice(prefix.length) : posix;
    const scene = sceneRelative(file);
    const entries = list
      .map((raw) => toEntry(path, file, scene, raw))
      .sort((a, b) => a.line - b.line || a.column - b.column);
    files.push({ path, file, scene, entries });
  }

  files.sort((a, b) => comparePath(a.scene, b.scene));
  return { scenes, files };
}

/** 数据里真实出现的诊断码 (按出现次数降序, 次数相同按码升序) */
export function codeStats(files: DiagnosticFile[]): CodeStat[] {
  const stats = new Map<string, CodeStat>();
  for (const file of files) {
    for (const entry of file.entries) {
      const current = stats.get(entry.code);
      if (current) current.count += 1;
      else stats.set(entry.code, { code: entry.code, severity: entry.severity, count: 1 });
    }
  }
  return [...stats.values()].sort((a, b) => b.count - a.count || comparePath(a.code, b.code));
}

/** 数据里真实出现的严重级别 (升序) */
export function presentSeverities(files: DiagnosticFile[]): Severity[] {
  const set = new Set<Severity>();
  for (const file of files) for (const entry of file.entries) set.add(entry.severity);
  return [...set].sort((a, b) => a - b);
}

/**
 * 按级别统计条数, 四个级别都在结果里 (没有的为 0)。
 *
 * 结果按 `SEVERITY_ORDER` 渲染成组头角标, 因此**角标的合计必须等于该组列出的行数** ——
 * 逐一 filter 数三个级别、漏掉第四个的写法, 一开启提示级就会让数字与行对不上。
 */
export function countBySeverity(entries: DiagnosticEntry[]): Record<Severity, number> {
  const counts: Record<Severity, number> = { 1: 0, 2: 0, 3: 0, 4: 0 };
  for (const entry of entries) counts[entry.severity] += 1;
  return counts;
}

/**
 * 默认筛选: 错误 + 警告。
 *
 * 若项目里压根没有错误和警告 (只有信息级建议), 默认就不能是"什么都不选" —— 那会让人
 * 打开列表看到一片空白, 以为功能坏了。这种极端情况下改为全选。
 */
export function defaultFilter(files: DiagnosticFile[]): DiagnosticFilter {
  const present = presentSeverities(files);
  const meaningful = present.filter((severity) => !SEVERITY_DEFAULT_OFF.includes(severity));
  return {
    severities: meaningful.length > 0 ? meaningful : present,
    codes: null,
    query: '',
  };
}

function matchesQuery(entry: DiagnosticEntry, query: string): boolean {
  const needle = query.trim().toLowerCase();
  if (!needle) return true;
  return (
    entry.message.toLowerCase().includes(needle) ||
    entry.file.toLowerCase().includes(needle) ||
    entry.code.toLowerCase().includes(needle)
  );
}

/** 按条件筛选; 返回的文件里不会有空组 */
export function filterDiagnosticFiles(files: DiagnosticFile[], filter: DiagnosticFilter): DiagnosticFile[] {
  const codes = filter.codes === null ? null : new Set(filter.codes);
  const severities = new Set(filter.severities);
  const result: DiagnosticFile[] = [];
  for (const file of files) {
    const entries = file.entries.filter(
      (entry) =>
        severities.has(entry.severity) && (codes === null || codes.has(entry.code)) && matchesQuery(entry, filter.query)
    );
    if (entries.length > 0) result.push({ ...file, entries });
  }
  return result;
}

export function countEntries(files: DiagnosticFile[]): number {
  return files.reduce((total, file) => total + file.entries.length, 0);
}

/** 当前筛选是否已偏离默认 (决定要不要给出"清除筛选") */
export function isFilterPerturbed(filter: DiagnosticFilter, fallback: DiagnosticFilter): boolean {
  const sameSeverities =
    filter.severities.length === fallback.severities.length &&
    filter.severities.every((severity) => fallback.severities.includes(severity));
  // `codes !== null` 也算偏离: 那表示用户动过诊断码面板, 即使他又把码全勾了回来,
  // "回到默认视图"仍然是合理的下一步。
  return filter.query.trim() !== '' || filter.codes !== null || !sameSeverities;
}

/**
 * 列表此刻能代表什么。
 *
 * - `pending`: 一个场景的结果都还没到, 列表**不能**说"没有问题";
 * - `clear`: 已经拿到结果, 项目里确实一条问题都没有;
 * - `problems`: 已经拿到结果, 且有问题 (可能被筛选挡到一条不剩)。
 */
export type DiagnosticsStanding = 'pending' | 'clear' | 'problems';

export interface DiagnosticsDescription {
  standing: DiagnosticsStanding;
  /** 标题下/旁那行小字: 项目规模与问题数 */
  description: string;
  /**
   * 列表为空时显示的主句。
   *
   * `null` 表示"数据里确实有问题, 空是筛选造成的": 那句话与"清除筛选"的入口都属于列表
   * 自己的行为, 由列表给出 (见 `DiagnosticsList`)。
   */
  emptyText: string | null;
}

/**
 * 还没收到任何结果时的措辞。
 *
 * 连接状态只影响这句话怎么说, 不影响判定: 已经收到过结果的场景不会因为断线就变回
 * "未诊断" —— 那份结果并没有消失 (见 `describeDiagnostics` 的 `scenes > 0` 分支)。
 */
const PENDING_DESCRIPTION: Record<LspStatus, string> = {
  disconnected: '语言服务未连接',
  connecting: '正在连接语言服务…',
  ready: '尚未收到诊断结果',
  error: '语言服务出错, 暂无诊断结果',
};

/**
 * 把"列表现在能说什么"收敛到一处 (弹窗与托盘共用)。
 *
 * 关键在于 `0 条问题` 有两种截然不同的原因: **扫过了, 确实没问题** 与 **结果还没来**。
 * 语言服务是逐个场景推送的 (没有问题的场景推空数组), 所以"已经收到过结果的场景数"
 * `scenes` 就是判据: 它为 0 时列表对项目一无所知, 那时说"没有发现问题"是在替语言服务
 * 下结论 —— 打开项目后的头几秒 (全量模拟可能要好几秒) 恰好是这个窗口。
 *
 * 反过来说, `scenes > 0` 之后就不再参考连接状态: 断线不会让已经收到的结果失效。
 * 极端情况是项目里一个场景文件都没有 —— 那时 `scenes` 永远是 0, 列表会一直停在
 * "尚未收到诊断结果", 这是刻意的: 它比谎称"没问题"要好。
 */
export function describeDiagnostics(options: {
  scenes: number;
  total: number;
  visible: number;
  hidden: number;
  lspStatus: LspStatus;
}): DiagnosticsDescription {
  const { scenes, total, visible, hidden, lspStatus } = options;
  const standing: DiagnosticsStanding = scenes === 0 ? 'pending' : total === 0 ? 'clear' : 'problems';

  if (standing === 'pending') {
    return { standing, description: PENDING_DESCRIPTION[lspStatus], emptyText: '还没有收到诊断结果' };
  }
  if (standing === 'clear') {
    return { standing, description: `${scenes} 个场景 · 0 条问题`, emptyText: '没有发现问题' };
  }
  const head = `${scenes} 个场景 · ${visible} 条问题`;
  return {
    standing,
    description: hidden > 0 ? `${head}（${hidden} 条已隐藏）` : head,
    // 有问题却一条都不显示, 只可能是筛选挡掉了
    emptyText: null,
  };
}

/**
 * 复制到剪贴板的 JSON。
 *
 * 行列都写成 1 起算, 与编辑器里看到的一致; 同时给出 `severity` 的语义名而不只是数字,
 * 这样一份导出贴给别人看时不需要再解释编码。
 */
export function buildDiagnosticsExport(options: {
  projectName: string;
  scope: { kind: 'project' } | { kind: 'file'; path: string };
  files: DiagnosticFile[];
  generatedAt?: string;
}): string {
  const payload = {
    project: options.projectName,
    generatedAt: options.generatedAt ?? new Date().toISOString(),
    scope: options.scope,
    files: options.files.map((file) => ({
      path: file.path,
      relPath: file.file,
      diagnostics: file.entries.map((entry) => ({
        severity: SEVERITY_NAMES[entry.severity],
        code: entry.code,
        line: entry.line,
        column: entry.column,
        endLine: entry.endLine,
        endColumn: entry.endColumn,
        message: entry.message,
      })),
    })),
  };
  return JSON.stringify(payload, null, 2);
}
